import pandas as pd


def _norm(x):
    """RTRIM(COALESCE(x, ''))"""
    if pd.isna(x):
        return ''
    return str(x).rstrip(' ')


def _sig(city, tier):
    return _norm(city) + '|' + _norm(tier)


def run(inputs: dict) -> dict:
    dim = inputs["dim_member"].copy()
    stg = inputs["stg_member"].copy()

    # Ensure proper dtypes / working copies
    dim = dim.reset_index(drop=True)

    # Build mutable lists to allow appending new rows and updating existing ones
    records = dim.to_dict("records")

    # Map member_id -> list of indices in records that are currently flagged is_current == 1
    def find_current_idx(member_id):
        for idx, rec in enumerate(records):
            if rec["member_id"] == member_id and rec["is_current"] == 1:
                return idx
        return None

    for _, s in stg.iterrows():
        member_id = s["member_id"]
        city_s = s["city"]
        tier_s = s["tier"]
        update_date = s["update_date"]

        cur_idx = find_current_idx(member_id)

        if cur_idx is None:
            # Insert new current row, staged values stored exactly as-is
            records.append({
                "member_id": member_id,
                "city": city_s,
                "tier": tier_s,
                "eff_start_date": update_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
        else:
            c = records[cur_idx]
            if _sig(city_s, tier_s) != _sig(c["city"], c["tier"]):
                # Close out current row
                records[cur_idx] = {
                    **c,
                    "eff_end_date": update_date,
                    "is_current": 0,
                }
                # Insert new current row
                records.append({
                    "member_id": member_id,
                    "city": city_s,
                    "tier": tier_s,
                    "eff_start_date": update_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            # else: no-op, keep c unchanged

    out = pd.DataFrame.from_records(
        records,
        columns=["member_id", "city", "tier", "eff_start_date", "eff_end_date", "is_current"],
    )

    # Coerce dtypes to match expected output schema
    out["member_id"] = out["member_id"].astype("int64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"]).astype("datetime64[us]")
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"]).astype("datetime64[us]")
    out["is_current"] = out["is_current"].astype("int64")

    return {"dim_member_out": out}
